  });

  it("returns 'local' when input is empty or consists purely of invalid characters", () => {
    expect(sanitizeUserId("")).toBe("local");
    expect(sanitizeUserId(undefined)).toBe("local");
    expect(sanitizeUserId("   ")).toBe("local");
