    const { decideRevalidationActions } = await import("../src/lib/proposal-revalidation");
    const actions = decideRevalidationActions(
      [{ id: "a" }, { id: "b" }, { id: "c" }],
      [
        { proposalId: "a", verdict: "withdraw", note: "played out" },
