    // Map CIK 0000320193 to AAPL in tasks table
    db.prepare(`
      INSERT INTO sec_ingest_jobs (id, idempotency_key, corpus_revision, status, created_at, updated_at)
      VALUES ('job1', 'idemp-1', 'corp-1', 'running', datetime('now'), datetime('now'))
