    })).toEqual({ degraded: true, reasons: ["never-synced"] });
  });

  it("marks unsynced local activity stale but keeps an idle caught-up database healthy", () => {
    expect(assessLitestreamRuntimeHealth({ ...healthy, ageSeconds: 3_601 }, {
