      ...healthy,
      lastSyncAt: null,
      ageSeconds: null,
      timestampState: "invalid"
    }, {
      liveMode: true,
      processUptimeSeconds: 600
    })).toEqual({ degraded: true, reasons: ["invalid-sync-time"] });
  });

  it("keeps a file signal diagnostic-only without degrading non-live development", () => {
