    }
    return { run: vi.fn(), get: vi.fn(), all: vi.fn(() => []) };
  });
  const database = {
    transaction: vi.fn((work: () => unknown) => ({ immediate: () => work() })),
    prepare
  };
  const getDb = vi.fn<() => any>(() => database);
  return {
    upsert,
    query,
    index,
    listIndexes: vi.fn(),
    describeIndex: vi.fn(),
    createIndex: vi.fn(),
    embed: vi.fn(),
    rerank,
    resolveApiKey: vi.fn(),
    getDb,
    audit: vi.fn(),
    listPaginated,
    fetchRecords,
    deleteMany,
    deleteAll,
