describe("Provider-dispatch PUSH boundary is always cost-free externally", () => {
  it("never includes costUsd in the pushed provider-dispatch event, even given a real local Voyage estimate", async () => {
    const { createProviderDispatchUsageMonitorEvent } = await import("../src/lib/usage-monitor-push");

    const event = await createProviderDispatchUsageMonitorEvent({
      sourceEventId: "voyage-attempt-1",
      occurredAt: "2026-07-15T00:00:00.000Z",
      provider: "voyage",
      operation: "embed document",
      credentialRef: "voyage-cred-fingerprint",
      userId: "local",
      outcome: "succeeded",
      requests: 1,
      // The exact kind of real, non-zero local estimate the fix above now produces — must not
      // leak into the pushed event (that's the RAG ledger lane's job, service "rag").
      estimatedCostUsd: 0.0042
    });

    expect(event.service).toBe("provider-dispatch");
    expect(event.provider).toBe("voyage");
    expect(event.costUsd).toBeUndefined();
    expect(event.metricType).toBe("usage");
    expect(event.billingMode).toBe("estimated");
  });

  it("stays cost-free even if a real actualCostUsd is ever supplied (defense against re-plumbing cost through this boundary)", async () => {
    const { createProviderDispatchUsageMonitorEvent } = await import("../src/lib/usage-monitor-push");

    const event = await createProviderDispatchUsageMonitorEvent({
      sourceEventId: "voyage-attempt-2",
      occurredAt: "2026-07-15T00:00:01.000Z",
      provider: "voyage",
      operation: "rerank",
      credentialRef: "voyage-cred-fingerprint",
      userId: "local",
      outcome: "succeeded",
      requests: 1,
      estimatedCostUsd: 0.0042,
      actualCostUsd: 0.0039
    });

    expect(event.costUsd).toBeUndefined();
    expect(event.metricType).toBe("usage");
  });

  it("stays cost-free for a zero-cost provider too (FMP convention unaffected)", async () => {
    const { createProviderDispatchUsageMonitorEvent } = await import("../src/lib/usage-monitor-push");

    const event = await createProviderDispatchUsageMonitorEvent({
      sourceEventId: "fmp-attempt-1",
      occurredAt: "2026-07-15T00:00:02.000Z",
      provider: "fmp",
      operation: "capability-quote",
      credentialRef: "fmp-cred-fingerprint",
      userId: "local",
      outcome: "succeeded",
      requests: 1,
      estimatedCostUsd: 0
    });

    expect(event.costUsd).toBeUndefined();
    expect(event.metricType).toBe("usage");
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => {
  const upsert = vi.fn();
  const query = vi.fn();
  const namespacedIndex = { upsert, query };
  const namespace = vi.fn(() => namespacedIndex);
  const index = vi.fn(() => ({ ...namespacedIndex, namespace }));
  const settings = new Map<string, string>();
  const manifests = new Map<string, { ledger_authority: string; provider_authority: string }>();
  const prepare = vi.fn((sql: string) => {
    if (sql.includes("INSERT OR IGNORE INTO settings")) return {
      run: vi.fn((key: string, value: string) => {
        if (!settings.has(key)) settings.set(key, value);
      })
    };
    if (sql.includes("SELECT value FROM settings WHERE key")) return {
      get: vi.fn((key: string) => settings.has(key) ? { value: settings.get(key) } : undefined)
    };
    if (sql.includes("INSERT OR IGNORE INTO vector_private_namespace_manifests")) return {
      run: vi.fn((tenantScope: string, ledgerAuthority: string, providerAuthority: string) => {
        if (!manifests.has(tenantScope)) {
          manifests.set(tenantScope, {
            ledger_authority: ledgerAuthority,
            provider_authority: providerAuthority
          });
        }
      })
    };
    if (sql.includes("FROM vector_private_namespace_manifests WHERE tenant_scope")) return {
      get: vi.fn((tenantScope: string) => manifests.get(tenantScope))
    };
    if (sql.includes("SELECT DISTINCT ledger_authority FROM vector_private_namespace_manifests")) return {
      all: vi.fn(() => [...manifests.values()].map(({ ledger_authority }) => ({ ledger_authority })))
    };
    if (sql.includes("SELECT DISTINCT ledger_authority") || sql.includes("SELECT COUNT(*) FROM vector_ingest_commits")) {
      return { all: vi.fn(() => []), get: vi.fn(() => ({ count: 0 })) };
    }
    return { run: vi.fn(), get: vi.fn(), all: vi.fn(() => []) };
  });
  const database = {
    transaction: vi.fn((work: () => unknown) => ({ immediate: () => work() })),
    prepare
  };
  return {
    upsert,
    query,
    index,
    listIndexes: vi.fn(),
    createIndex: vi.fn(),
    embed: vi.fn(),
    resolveApiKey: vi.fn(),
    namespace,
    settings,
    manifests,
    getDb: vi.fn(() => database)
  };
});

